  "192c7sz": "d7 बिशपचा बचाव केवळ f6 शूरवीर करतो. शूरवीर प्रथम घ्या, नंतर रॉक बिशपला घेऊन जातो!",
  "17vfw2k": "ओव्हरलोडेड तुकडा",
