  "3vfpc2": "जबरदस्तीने हालचालीने सुरुवात करा! 2 मध्ये मॅट.",
  "ai8bft": "विजय मिळवणारा पवित्रता",
  "1c4vdgv": "एका बचावपटूला दोन नोकऱ्या आहेत. 2 मध्ये मॅट!",
  "1ovpig9": "खेळ पूर्ण करणे",
  "1s3t19v": "पुढे जाण्याचा अर्थ असा नाही की तुम्ही पूर्ण केल्याशिवाय काहीही नाहीः कृष्णवर्णीय राजाला बहुतेक 15 हालचालींमध्येमेट करा!",
  "1v92uft": "स्टेज 2 चे पुनरावलोकन",
